//! Review02 scratch probes: lawful-kind callback variance, duplicates, missing and unknown keys.
use opensip_native_wire_carrier_trial::wire::*;
use serde::Deserialize;
use serde::de::value::{Error, MapDeserializer};
use serde::de::{IntoDeserializer, Visitor};

enum P { T(&'static str), Unit, None, U(u64), I(i64), U8(u8), B(Vec<u8>), BB(&'static [u8]), Char(char), Bool(bool), Some(Box<P>), Newtype(&'static str), Empty }
impl<'de> IntoDeserializer<'de, Error> for P {
    type Deserializer = Self;
    fn into_deserializer(self) -> Self { self }
}
impl<'de> serde::Deserializer<'de> for P {
    type Error = Error;
    fn deserialize_any<V: Visitor<'de>>(self, v: V) -> Result<V::Value, Error> {
        match self {
            P::T(s) => v.visit_borrowed_str(s),
            P::Unit => v.visit_unit(),
            P::None => v.visit_none(),
            P::U(x) => v.visit_u64(x),
            P::I(x) => v.visit_i64(x),
            P::U8(x) => v.visit_u8(x),
            P::B(b) => v.visit_byte_buf(b),
            P::BB(b) => v.visit_borrowed_bytes(b),
            P::Char(c) => v.visit_char(c),
            P::Bool(b) => v.visit_bool(b),
            P::Some(inner) => v.visit_some(*inner),
            P::Newtype(s) => v.visit_newtype_struct(P::T(s)),
            P::Empty => v.visit_seq(serde::de::value::SeqDeserializer::new(std::iter::empty::<P>())),
        }
    }
    serde::forward_to_deserialize_any! {
        bool i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f32 f64 char str string bytes byte_buf option unit
        unit_struct newtype_struct seq tuple tuple_struct map struct enum identifier ignored_any
    }
}

fn show<T, E: std::fmt::Display>(label: &str, r: Result<T, E>) {
    match r { Ok(_) => println!("ACCEPT  {label}"), Err(e) => println!("refuse  {label}: {e}") }
}
fn file() -> Vec<(&'static str, P)> {
    vec![("path", P::T("a")), ("kind", P::T("file")), ("byteLength", P::U(5)), ("contentSha256", P::T("d")),
         ("executable", P::Bool(true)), ("targetBytes", P::Unit)]
}
fn symlink() -> Vec<(&'static str, P)> {
    vec![("targetBytes", P::BB(&[0xff])), ("executable", P::Unit), ("contentSha256", P::Unit), ("byteLength", P::Unit),
         ("path", P::T("l")), ("kind", P::T("symlink"))]
}
fn set(mut base: Vec<(&'static str, P)>, key: &str, value: P) -> Vec<(&'static str, P)> {
    let i = base.iter().position(|(k, _)| *k == key).unwrap();
    base[i].1 = value;
    base
}
fn rust3(values: Vec<(&'static str, P)>) -> Result<Rust3SnapshotEntryV2, Error> {
    Rust3SnapshotEntryV2::deserialize(MapDeserializer::new(values.into_iter()))
}

#[test]
fn lawful_and_wrong_kinds() {
    show("file baseline", rust3(file()));
    show("symlink baseline (tag last, borrowed bytes)", rust3(symlink()));
    show("lawful null via visit_none", rust3(set(file(), "targetBytes", P::None)));
    show("null via visit_some(unit)", rust3(set(file(), "targetBytes", P::Some(Box::new(P::Unit)))));
    show("lawful uint via visit_u8", rust3(set(file(), "byteLength", P::U8(5))));
    show("lawful uint via visit_i64(5)", rust3(set(file(), "byteLength", P::I(5))));
    show("negative via visit_i64(-1)", rust3(set(file(), "byteLength", P::I(-1))));
    show("text via visit_char", rust3(set(file(), "path", P::Char('a'))));
    show("text via newtype", rust3(set(file(), "path", P::Newtype("a"))));
    show("bool <- u64 1", rust3(set(file(), "executable", P::U(1))));
    show("null <- empty seq", rust3(set(file(), "targetBytes", P::Empty)));
    show("tag <- u64", rust3(set(file(), "kind", P::U(0))));
    show("tag <- char", rust3(set(file(), "kind", P::Char('f'))));
    show("tag unknown value", rust3(set(file(), "kind", P::T("dir"))));
    let mut dup = file(); dup.push(("path", P::T("b")));
    show("duplicate member", rust3(dup));
    let mut duptag = file(); duptag.push(("kind", P::T("file")));
    show("duplicate tag", rust3(duptag));
    let mut unknown = file(); unknown.push(("surprise", P::Unit));
    show("unknown key", rust3(unknown));
    let mut missing = file(); missing.retain(|(k, _)| *k != "targetBytes");
    show("missing required null", rust3(missing));
    let mut notag = file(); notag.retain(|(k, _)| *k != "kind");
    show("missing tag", rust3(notag));
    show("flat Option via visit_none (comparison)", Ts2CancelledV1::deserialize(MapDeserializer::<_, Error>::new(
        vec![("executionId", P::None), ("analysisOrdinal", P::None), ("observedPhase", P::T("snapshot"))].into_iter())));
    show("flat u64 via visit_i64(5) (comparison)", Ts2SnapshotAcceptedV1::deserialize(MapDeserializer::<_, Error>::new(
        vec![("snapshotId", P::T("s")), ("manifestSha256", P::T("a")), ("entryCount", P::I(5)), ("totalFileBytes", P::U(0)), ("totalChunkCount", P::U(0))].into_iter())));
}

#[test]
fn json_tagged_edges() {
    let base = r#""path":"a","byteLength":1,"contentSha256":"b","linkTarget":null"#;
    show("json baseline", serde_json::from_str::<Ts2SnapshotEntryV1>(&format!(r#"{{"kind":"file",{base}}}"#)));
    show("json duplicate member", serde_json::from_str::<Ts2SnapshotEntryV1>(&format!(r#"{{"kind":"file",{base},"path":"z"}}"#)));
    show("json duplicate tag", serde_json::from_str::<Ts2SnapshotEntryV1>(&format!(r#"{{"kind":"file",{base},"kind":"file"}}"#)));
    show("json escaped key", serde_json::from_str::<Ts2SnapshotEntryV1>(r#"{"kind":"file","path":"a","byteLength":1,"contentSha256":"b","linkTarget":null}"#));
    show("json array instead of map", serde_json::from_str::<Ts2SnapshotEntryV1>(r#"["file","a",1,"b",null]"#));
    show("json unknown key with nested value", serde_json::from_str::<Ts2SnapshotEntryV1>(&format!(r#"{{"kind":"file",{base},"x":{{"y":[1]}}}}"#)));
    let v: Ts2SnapshotEntryV1 = serde_json::from_str(&format!(r#"{{{base},"kind":"file"}}"#)).unwrap();
    println!("tag-last reserialized (derived Serialize order): {}", serde_json::to_string(&v).unwrap());
    let a: Rust3AnchorRefV1 = serde_json::from_str(r#"{"kind":"fact-ref","snapshotId":null,"path":null,"contentSha256":null,"startByte":null,"endByte":null,"factId":"f"}"#).unwrap();
    let text = serde_json::to_string(&a).unwrap();
    show(&format!("anchor round trip {text}"), serde_json::from_str::<Rust3AnchorRefV1>(&text));
}

