//! Review02 grammar stress: generated tagged reader for keyword tag, quoted tag, enum/const text, alias bytes, null.
use opensip_native_wire_carrier_trial::wire::*;
use serde::Deserialize;
use serde::de::value::{Error, MapDeserializer};
use serde::de::{IntoDeserializer, Visitor};

enum P { T(&'static str), Unit, U(u64), B(Vec<u8>), Bool(bool) }
impl<'de> IntoDeserializer<'de, Error> for P {
    type Deserializer = Self;
    fn into_deserializer(self) -> Self { self }
}
impl<'de> serde::Deserializer<'de> for P {
    type Error = Error;
    fn deserialize_any<V: Visitor<'de>>(self, v: V) -> Result<V::Value, Error> {
        match self { P::T(s) => v.visit_str(s), P::Unit => v.visit_unit(), P::U(x) => v.visit_u64(x), P::B(b) => v.visit_byte_buf(b), P::Bool(b) => v.visit_bool(b) }
    }
    serde::forward_to_deserialize_any! {
        bool i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f32 f64 char str string bytes byte_buf option unit
        unit_struct newtype_struct seq tuple tuple_struct map struct enum identifier ignored_any
    }
}
fn show<T: std::fmt::Debug, E: std::fmt::Display>(label: &str, r: Result<T, E>) {
    match r { Ok(v) => println!("ACCEPT  {label}: {v:?}"), Err(e) => println!("refuse  {label}: {e}") }
}
fn quoted(mode: &'static str, blob: P) -> Vec<(&'static str, P)> {
    vec![("mode", P::T(mode)), ("type", P::T("a\"b")), ("flag", P::Bool(false)), ("count", P::U(99)),
         ("blob", blob), ("nothing", P::Unit), ("ref", P::T("r"))]
}

#[test]
fn stress_grammar() {
    let decode = |v: Vec<(&'static str, P)>| Ts2ProbeTaggedV1::deserialize(MapDeserializer::<_, Error>::new(v.into_iter()));
    show("quoted tag, enum x, bytes alias, inert const", decode(quoted("x", P::B(vec![1, 2]))));
    show("quoted tag, enum z (not declared)", decode(quoted("z", P::B(vec![1]))));
    show("quoted tag, blob as text", decode(quoted("x", P::T("01"))));
    let ok = r#"{"type":"self","mode":"x","flag":false,"count":null,"blob":null,"nothing":"t","ref":null}"#;
    show("self tag json", serde_json::from_str::<Ts2ProbeTaggedV1>(ok));
    show("self tag const mode y", serde_json::from_str::<Ts2ProbeTaggedV1>(&ok.replace(r#""mode":"x""#, r#""mode":"y""#)));
    show("self tag flag null", serde_json::from_str::<Ts2ProbeTaggedV1>(&ok.replace(r#""flag":false"#, r#""flag":null"#)));
    let v: Ts2ProbeTaggedV1 = serde_json::from_str(ok).unwrap();
    println!("reserialized: {}", serde_json::to_string(&v).unwrap());
